//! App-level APIs: name / version / exit / relaunch.
//!
//! Name + version are set by the backend on startup via `app.setInfo`.
//! The frontend then queries via `app.getName` / `app.getVersion`.
//! Exit + relaunch are uniform across runtimes.
//!
//! Dispatch is generated by `#[tynd::handler]` (U10).

use std::{sync::LazyLock, time::Duration};

use parking_lot::Mutex;
use serde_json::Value;

use crate::{ipc_error::IpcError, tynd};

// `LazyLock` initializes the inner `Mutex<String>` to `String::new()`
// on first access — empty string is the sentinel for "the backend
// hasn't called `app.setInfo` yet" so the getters fall back to the
// process-derived default. The previous `OnceLock` shape used `None`
// for the same purpose; the empty-string check is equivalent and saves
// the per-call `Option::map` boilerplate.
static APP_NAME: LazyLock<Mutex<String>> = LazyLock::new(|| Mutex::new(String::new()));
static APP_VERSION: LazyLock<Mutex<String>> = LazyLock::new(|| Mutex::new(String::new()));
static BUNDLE_ID: LazyLock<Mutex<String>> = LazyLock::new(|| Mutex::new(String::new()));

/// Tynd host version — baked in at compile time from the workspace Cargo.toml.
const FRAMEWORK_VERSION: &str = env!("CARGO_PKG_VERSION");

/// Marker for the `#[tynd::handler]` dispatch table — app state lives
/// in the file-level `APP_NAME` / `APP_VERSION` / `BUNDLE_ID` statics.
#[derive(Debug, Default)]
pub struct AppApi;

#[tynd::handler(api = "app")]
impl AppApi {
    /// Return the app's display name. Defaults to the running
    /// binary's filename when the backend hasn't called `setInfo`.
    pub fn get_name() -> String {
        get_name()
    }

    /// Return the app version string. Defaults to `"0.0.0"` when the
    /// backend hasn't called `setInfo`.
    pub fn get_version() -> String {
        get_version()
    }

    /// Return the Tynd framework version baked into this host.
    pub fn get_framework_version() -> String {
        FRAMEWORK_VERSION.to_string()
    }

    /// Return the app's bundle identifier (reverse-DNS string), or
    /// `null` when the backend hasn't called `setInfo`.
    pub fn get_bundle_identifier() -> Option<String> {
        get_bundle_id()
    }

    /// Set the app's display metadata. Each field is optional —
    /// supply only the keys you want to update.
    pub fn set_info(
        name: Option<String>,
        version: Option<String>,
        bundle_id: Option<String>,
    ) {
        if let Some(n) = name {
            *APP_NAME.lock() = n;
        }
        if let Some(v) = version {
            *APP_VERSION.lock() = v;
        }
        if let Some(b) = bundle_id {
            *BUNDLE_ID.lock() = b;
        }
    }

    /// Exit the host process with `code` (default `0`). Runs the
    /// cleanup hook chain before terminating. Never returns.
    ///
    /// Calls `tynd_host_core::hooks::run_cleanup` so the OS layer
    /// doesn't depend on the higher app crate (cycle break).
    pub fn exit(code: Option<i64>) {
        tynd_host_core::hooks::run_cleanup();
        std::process::exit(code.unwrap_or(0) as i32);
    }

    /// Spawn a fresh copy of the running binary, then exit the
    /// current process. Used by self-update flows that want a clean
    /// state at re-launch.
    pub fn relaunch() -> Result<Value, String> {
        let exe = std::env::current_exe().map_err(|e| {
            String::from(IpcError::new("app", "relaunch", format!("current_exe: {e}")))
        })?;
        std::process::Command::new(&exe).spawn().map_err(|e| {
            String::from(IpcError::new("app", "relaunch", format!("spawn: {e}")))
        })?;
        std::thread::spawn(|| {
            // Small delay so the child process is actually underway before we exit.
            std::thread::sleep(Duration::from_millis(100));
            tynd_host_core::hooks::run_cleanup();
            std::process::exit(0);
        });
        Ok(Value::Null)
    }
}

fn get_bundle_id() -> Option<String> {
    let v = BUNDLE_ID.lock();
    if v.is_empty() {
        None
    } else {
        Some(v.clone())
    }
}

fn get_name() -> String {
    let v = APP_NAME.lock();
    if !v.is_empty() {
        return v.clone();
    }
    drop(v);
    // Fallback: filename of the running binary without extension.
    std::env::current_exe()
        .ok()
        .and_then(|p| p.file_stem().map(|s| s.to_string_lossy().into_owned()))
        .unwrap_or_else(|| "tynd".into())
}

fn get_version() -> String {
    let v = APP_VERSION.lock();
    if v.is_empty() {
        "0.0.0".into()
    } else {
        v.clone()
    }
}
